/* ── Component: ImagePreviewPage ────────────────────────────── */
const ImagePreviewPage = (() => {
  /* ── State ─────────────────────────────────────────────────── */
  let isOpen = false;
  let lastFocusedElement = null;

  /* ── Element refs ──────────────────────────────────────────── */
  const overlay   = document.getElementById('delete-modal-overlay');
  const dialog    = document.getElementById('delete-modal');
  const openBtn   = document.getElementById('delete-trigger');
  const closeBtn  = document.getElementById('modal-close-btn');
  const cancelBtn = document.getElementById('modal-cancel-btn');
  const confirmBtn= document.getElementById('modal-confirm-btn');

  /* ── Focus trap helpers ────────────────────────────────────── */
  const FOCUSABLE = [
    'a[href]',
    'button:not([disabled])',
    'input:not([disabled])',
    'select:not([disabled])',
    'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])',
  ].join(', ');

  function getFocusable() {
    return Array.from(dialog.querySelectorAll(FOCUSABLE));
  }

  function trapFocus(e) {
    const focusable = getFocusable();
    const first = focusable[0];
    const last  = focusable[focusable.length - 1];

    if (e.key === 'Tab') {
      if (e.shiftKey) {
        if (document.activeElement === first) { e.preventDefault(); last.focus(); }
      } else {
        if (document.activeElement === last)  { e.preventDefault(); first.focus(); }
      }
    }

    if (e.key === 'Escape') closeModal();
  }

  /* ── Open / close ──────────────────────────────────────────── */
  function openModal() {
    isOpen = true;
    lastFocusedElement = document.activeElement;

    overlay.classList.add('is-open');
    dialog.removeAttribute('aria-hidden');
    overlay.removeAttribute('aria-hidden');

    // Move focus into dialog after paint so animation doesn't interfere
    requestAnimationFrame(() => {
      closeBtn.focus();
    });

    document.addEventListener('keydown', trapFocus);
    overlay.addEventListener('mousedown', handleBackdropClick);
  }

  function closeModal() {
    isOpen = false;

    overlay.classList.remove('is-open');
    dialog.setAttribute('aria-hidden', 'true');
    overlay.setAttribute('aria-hidden', 'true');

    document.removeEventListener('keydown', trapFocus);
    overlay.removeEventListener('mousedown', handleBackdropClick);

    // Restore focus to trigger
    if (lastFocusedElement) lastFocusedElement.focus();
  }

  /* Close when clicking the backdrop (not the dialog itself) */
  function handleBackdropClick(e) {
    if (e.target === overlay) closeModal();
  }

  /* ── Confirm delete ────────────────────────────────────────── */
  function confirmDelete() {
    closeModal();
    // Announce to screen readers
    const live = document.getElementById('status-live');
    live.textContent = 'Image "Golden Hour — Kyoto" has been deleted from your library.';
    // Visual feedback: fade out the card
    document.getElementById('image-card').style.opacity = '0.35';
    openBtn.disabled = true;
    openBtn.textContent = 'Deleted';
  }

  /* ── Wire events ───────────────────────────────────────────── */
  openBtn.addEventListener('click', openModal);
  closeBtn.addEventListener('click', closeModal);
  cancelBtn.addEventListener('click', closeModal);
  confirmBtn.addEventListener('click', confirmDelete);

  return { openModal, closeModal };
})();

